use hec_native_ic::{jac::Curve,poly::Poly,rng::Rng};
use crate::{linear::{Linear,Projector,Sparse,put},prepared::Prepared,table_oracle::{split,OracleStats}};
#[path="inverse.rs"] mod inverse;
#[derive(Debug,Default,Clone,PartialEq)]pub struct Stats{pub attempted:bool,pub trials:usize,pub split:usize,pub ungrounded:usize,pub zero:usize,pub nodes:usize,pub terms:usize,pub bound_exhausted:bool,pub determining:bool}
fn brute(mut h:Poly,c:&Curve)->Option<std::collections::BTreeMap<u64,u32>>{let mut roots=std::collections::BTreeMap::new();for x in 0..c.fp.p{while h.deg()>0&&h.eval(x,&c.fp)==0{h=h.div_exact(&Poly::x_minus(x,&c.fp),&c.fp);*roots.entry(x).or_insert(0)+=1;}}if h.deg()==0{Some(roots)}else{None}}
pub fn run(c:&Curve,l:&Linear,prep:&Prepared,seed:u64,audit:bool)->(Stats,Option<(u64,Sparse)>){let mut stats=Stats{attempted:true,..Stats::default()};let ids=l.grounded_indices();if ids.len()<c.g+1{stats.bound_exhausted=true;return(stats,None);}let mut grounded=vec![false;l.len];for &j in &ids{grounded[j]=true;}let mut projector=Projector::new(l,audit);let mut index=vec![usize::MAX;c.fp.p as usize];for(j,&(x,_))in prep.fb.iter().enumerate(){index[x as usize]=j;}let mut rng=Rng::new(seed);
for trial in 0..128{stats.trials=trial+1;let mut selected=vec![];while selected.len()<c.g+1{let j=ids[rng.below(ids.len()as u64)as usize];if !selected.contains(&j){selected.push(j);}}let mut points=vec![];let mut signed=vec![];let mut u=Poly::one();for j in selected{let s=if rng.below(2)==0{1}else{-1};let(x,y)=prep.fb[j];let y=if s==1{y}else{c.fp.neg(y)};points.push((x,y));signed.push((j,s));u=u.mul(&Poly::x_minus(x,&c.fp),&c.fp);}let mut bases=vec![];let mut den=vec![];for &(x,_)in &points{let mut q=vec![0;c.g+1];q[c.g]=1;for i in(0..c.g).rev(){q[i]=c.fp.add(u.c[i+1],c.fp.mul(x,q[i+1]));}let q=Poly::from_coeffs(&q);if audit{assert_eq!(q.mul(&Poly::x_minus(x,&c.fp),&c.fp),u);}den.push(q.eval(x,&c.fp));bases.push(q);}let inv=inverse::invert(&den,&c.fp);let mut v=Poly::zero();for(i,&(_,y))in points.iter().enumerate(){v=v.add(&bases[i].scale(c.fp.mul(y,inv[i]),&c.fp),&c.fp);}let norm=c.f.sub(&v.mul(&v,&c.fp),&c.fp);let(h,rem)=norm.divrem(&u,&c.fp);assert!(rem.is_zero());assert_eq!(h.deg(),c.g as isize);assert_eq!(h.lc(),1);if audit{for &(x,y)in &points{assert_eq!(v.eval(x,&c.fp),y);}assert_eq!(u.mul(&h,&c.fp),norm);}let roots=split(&h,&c.fp,&mut OracleStats::default(),&prep.roots);if audit{let truth=brute(h,c);assert_eq!(roots.is_some(),truth.is_some());if let Some(ref roots)=roots{assert_eq!(roots.as_slice().iter().copied().collect::<std::collections::BTreeMap<_,_>>(),truth.unwrap());}}let Some(roots)=roots else{continue;};stats.split+=1;let mut all=true;let mut native=c.zero();if audit{for &(x,y)in &points{native=c.add_place(&native,x,y);}}for &(x,mult)in roots.as_slice(){let y=v.eval(x,&c.fp);let j=index[x as usize];assert_ne!(j,usize::MAX);let s=if y==prep.fb[j].1{1}else{assert_eq!(y,c.fp.neg(prep.fb[j].1));-1};signed.push((j,s*mult as i64));all&=grounded[j];if audit{for _ in 0..mult{native=c.add_place(&native,x,y);}}}if audit{assert!(c.is_zero(&native));}if !all{stats.ungrounded+=1;continue;}let(mut a,mut b)=(0,0);let mut row=Sparse::new();for(j,s)in signed{let(x,y)=projector.point(j);let w=l.f.from_i64(s);a=l.f.add(a,l.f.mul(w,x));b=l.f.add(b,l.f.mul(w,y));put(&mut row,if j<l.m{j}else{j+1},w,&l.f);}if b==0{assert_eq!(a,0);stats.zero+=1;continue;}let k=l.f.mul(l.f.neg(a),l.f.inv(b));stats.nodes=projector.nodes;stats.terms=projector.terms;stats.determining=true;return(stats,Some((k,row)));}
stats.nodes=projector.nodes;stats.terms=projector.terms;stats.bound_exhausted=true;(stats,None)}
